"""Apply the reviewed public-content components to the compiled React bundle.

The original React component source is not present in this repository. This
script keeps the intentional component replacements reviewable and repeatable
instead of leaving undocumented byte-level edits in src/js/rekonet.js.
"""

from pathlib import Path

BUNDLE = Path(__file__).resolve().parents[1] / "src" / "js" / "rekonet.js"
source = BUNDLE.read_text(encoding="utf-8")


def replace_range(start_marker: str, end_marker: str, replacement: str) -> None:
    global source
    start = source.find(start_marker)
    if start < 0:
        raise RuntimeError(f"start marker not found: {start_marker}")
    end = source.find(end_marker, start)
    if end < 0:
        raise RuntimeError(f"end marker not found after {start_marker}: {end_marker}")
    source = source[:start] + replacement.strip() + source[end:]


